import java.util.*;

class Solution {
    public int bestHarvest(TreeNode root) {
        int[] r = dfs(root);
        return Math.max(r[0], r[1]);
    }

    // returns {best if node is harvested, best if node is skipped}
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] l = dfs(node.left), r = dfs(node.right);
        int take = node.val + l[1] + r[1];                          // children must be skipped
        int skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);     // children are free
        return new int[]{take, skip};
    }
}

