class Solution:
    def bestHarvest(self, root: Optional[TreeNode]) -> int:
        # iterative post-order to avoid deep recursion
        if not root: return 0
        order, st = [], [root]
        while st:
            n = st.pop(); order.append(n)
            if n.left: st.append(n.left)
            if n.right: st.append(n.right)
        res = {None: (0, 0)}
        for n in reversed(order):
            lt, ls = res[n.left]; rt, rs_ = res[n.right]
            res[n] = (n.val + ls + rs_, max(lt, ls) + max(rt, rs_))
        return max(res[root])

