function bestHarvest(root) {
  if (!root) return 0;
  const order = [], st = [root];
  while (st.length) { const n = st.pop(); order.push(n); if (n.left) st.push(n.left); if (n.right) st.push(n.right); }
  const take = new Map(), skip = new Map();
  const T = n => n ? take.get(n) : 0, S = n => n ? skip.get(n) : 0;
  for (let i = order.length - 1; i >= 0; i--) {
    const n = order[i];
    take.set(n, n.val + S(n.left) + S(n.right));
    skip.set(n, Math.max(T(n.left), S(n.left)) + Math.max(T(n.right), S(n.right)));
  }
  return Math.max(T(root), S(root));
}
